import { mkdtempSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import type { FastifyInstance } from 'fastify';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { buildApp } from '../src/app';

// The PWA files are generated by vite-plugin-pwa; the server only needs to serve them with the right headers,
// so the fixture writes placeholders with the same names.
const PWA_FILES = ['sw.js', 'workbox-abc123.js', 'registerSW.js', 'manifest.webmanifest'];

let app: FastifyInstance;

beforeAll(async () => {
  const dir = mkdtempSync(join(tmpdir(), 'easy-grades-pwa-'));
  writeFileSync(join(dir, 'index.html'), '<!doctype html><title>Easy Grades</title>');
  for (const name of PWA_FILES) writeFileSync(join(dir, name), '{}');
  app = await buildApp({ staticDir: dir });
});

afterAll(async () => {
  await app.close();
});

describe('PWA static files', () => {
  it.each(['/sw.js', '/workbox-abc123.js', '/registerSW.js', '/manifest.webmanifest'])(
    'serves %s with no-cache so updates reach the browser',
    async (url) => {
      const res = await app.inject({ method: 'GET', url });
      expect(res.statusCode).toBe(200);
      expect(res.headers['cache-control']).toBe('no-cache');
    },
  );

  it('serves the manifest as application/manifest+json', async () => {
    const res = await app.inject({ method: 'GET', url: '/manifest.webmanifest' });
    expect(res.headers['content-type']).toBe('application/manifest+json');
  });

  it('serves the service worker as JavaScript', async () => {
    const res = await app.inject({ method: 'GET', url: '/sw.js' });
    expect(res.headers['content-type']).toMatch(/^(application|text)\/javascript/);
  });

  it('keeps the index.html fallback for app routes', async () => {
    const res = await app.inject({ method: 'GET', url: '/visao-geral' });
    expect(res.statusCode).toBe(200);
    expect(res.body).toContain('Easy Grades');
  });
});

describe('Content-Security-Policy', () => {
  it('allows the service worker and the manifest from the same origin only', async () => {
    const res = await app.inject({ method: 'GET', url: '/' });
    const csp = res.headers['content-security-policy'];
    expect(csp).toEqual(expect.stringContaining("worker-src 'self'"));
    expect(csp).toEqual(expect.stringContaining("manifest-src 'self'"));
  });
});
